const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
const isResume = input.intent === 'resume_after_approval' || input.input?.approved === true;
const text = (JSON.stringify(input || {}) + ' ' + aiText).toLowerCase();
const isCreateSkill = input.intent === 'create_skill' || input.context?.route_decision?.decision === 'create_skill' || /\b(create|shape|design|draft)\s+(a\s+)?(new\s+)?skill\b/i.test(text);
const externalWrite = /\b(send|email|mail|invite|schedule|calendar|meeting invite|publish|commit|delete|external write)\b/i.test(text);
const approvalRequired = !isResume && (isCreateSkill || externalWrite);
const gate = isCreateSkill ? 'skill_spec_approval' : externalWrite ? 'requires_human_action' : null;
const approval = approvalRequired ? {
  required: true,
  gate,
  summary: isCreateSkill ? 'Human approval is required before a generated skill or task-agent design becomes active.' : 'Human approval is required before Agentic Butler performs an external write action.',
  proposed_action: isCreateSkill ? 'Create a pending skill draft and keep it behind human approval.' : 'Pause before sending, scheduling, publishing, deleting, committing, or making an external commitment.'
} : { required: false };
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: approvalRequired ? 'approval_required' : 'completed',
  approval,
  output: {
    summary: aiText || (isResume ? 'Agentic Butler resumed after human approval.' : 'Agentic Butler completed autonomous internal skill orchestration.'),
    approval_request: approvalRequired ? approval : null,
    skill_run: { mode: isResume ? 'resumed_after_approval' : approvalRequired ? 'approval_gated' : 'autonomous_internal', execute: !approvalRequired },
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Agentic Butler AI Agent' }
  },
  trace: { stored: true, trace_id: 'n8n_exec_' + executionId, used_agents: ['agentic_butler_ai_agent', 'skill_orchestrator_internal_component', 'actor_twin_checkpoint_boundary'], target_agent: 'agentic_butler', route_decision: isCreateSkill ? 'create_skill' : 'activate_skill', handoff_status: approvalRequired ? 'approval_required' : 'completed_autonomous', parent_trace_id: input.context?.handoff_trace_id || input.context?.actor_trace_id || '', ai_agent_integrated: true }
};
return [{ json: response }];

